    local_temperatures = jnp.array([0.571429, 0.606061, 0.555556, 0.555556, 0.666667, 0.526316, 0.555556, 0.571429, 0.5, 0.588235, 0.571429, 0.571429, 0.571429, 0.588235, 0.540541, 0.571429, 0.571429, 0.512821, 0.540541, 0.588235, 0.606061, 0.526316, 0.555556, 0.555556, 0.512821, 0.588235, 0.540541, 0.540541, 0.540541, 0.512821, 0.588235, 0.588235, 0.555556, 0.526316, 0.606061, 0.588235, 0.512821, 0.645161, 0.625, 0.625], dtype=jnp.float32)
